parse_args.source:
def parse_args():
    p = argparse.ArgumentParser()
    p.add_argument("--date", default=str(date.today()))
    p.add_argument("--full-refresh", action="store_true")
    p.add_argument("--no-alerts", action="store_true")
    return p.parse_args()

load_stations.source:
def load_stations(db_path):
    """Fetch station metadata (name, region, elevation)."""
    with sqlite3.connect(db_path) as conn:
        return pd.read_sql_query("SELECT station_id, name, region, elevation_m FROM stations", conn)

dedupe.source:
def dedupe(df):
    """Sensors sometimes resend a reading; keep the first."""
    return df.drop_duplicates(subset=["station_id", "timestamp"], keep="first")

clean.source:
def clean(df):
    for step in (to_celsius, drop_invalid, dedupe):
        df = step(df)
    return df

enrich.source:
def enrich(df, stations):
    """Attach station name and region to every reading."""
    return df.merge(stations, on="station_id", how="left")

flag_anomalies.source:
def flag_anomalies(summary):
    """Stations whose daily mean is far from their region's mean."""
    g = summary.groupby("region")["mean"]
    z = (summary["mean"] - g.transform("mean")) / g.transform("std").replace(0, np.nan)
    return summary[z.abs() > ANOMALY_Z].copy()

save_summary.source:
def save_summary(summary, full_refresh=False):
    with sqlite3.connect(STATIONS_DB) as conn:
        if full_refresh:
            conn.execute("DELETE FROM daily_summary")
        summary.assign(day=summary["day"].astype(str)).to_sql("daily_summary", conn, if_exists="append", index=False)
        return len(summary)

send_alert.source:
def send_alert(anomalies):
    payload = {"count": len(anomalies),
               "stations": anomalies[["station_id", "name", "mean"]].to_dict(orient="records")}
    r = requests.post(ALERT_WEBHOOK, json=payload, timeout=10)
    return r.status_code
